Lemma optit_cells_after_shift : forall r lst cur err pad7,
  optit_cells_after (tk_shift r) lst cur err pad7 = optit_cells_after r lst (cur + 1) err pad7.
Proof.
  intros [| |k l] lst cur err pad7; cbn; try reflexivity. unfold OptItCells.
  replace (cur + Z.of_nat (S k)) with (cur + 1 + Z.of_nat k) by lia. reflexivity.
Qed.
(* [comment removed for export] *)
Lemma optit_cells_after_shiftn : forall n r lst cur err pad7,
  optit_cells_after (tk_shiftn n r) lst cur err pad7 = optit_cells_after r lst (cur + Z.of_nat n) err pad7.
Proof.
  induction n as [|n IH]; intros r lst cur err pad7; cbn [tk_shiftn].
  - rewrite Z.add_0_r. reflexivity.
  - rewrite optit_cells_after_shift, IH. f_equal. lia.
Qed.
