(* [comment removed for export] *)
Definition ok_side (m : mem) (A SP n lst : Z) : Prop :=
  ACONST m /\ aobj m A SZ_TOKIT /\ accessible m SP n /\ accessible m lst 16.

Lemma ok_side_now : forall m m1 A SP n lst lo hi,
  ok_side m A SP n lst -> munch [(lo, hi); (A, A + SZ_TOKIT)]%Z m m1 -> wmono bsegs m m1 -> aceil <= lo ->
  ok_side m1 A SP n lst.
Proof.
  intros m m1 A SP n lst lo hi (AC & AO & AW & AL) MU WM CEIL.
  assert (FW : Forall awin [(lo, hi); (A, A + SZ_TOKIT)]%Z)
    by (apply Forall_cons; [apply awin_stack; exact CEIL| apply Forall_cons; [exact (aobj_awin _ _ _ AO)| apply Forall_nil]]).
  split; [eapply aconst_transport_awin; fast_eassumption|].
  split; [eapply aobj_transport; fast_eassumption|].
  split; eapply acc_transport_awin; fast_eassumption.
Qed.

Definition optit_post_c (cells : list cell) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (A lst SP lo : Z) (sbs : list byte) (lrest : list cell) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (A, A + SZ_TOKIT)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' A cells
    /\ rw_cells bsegs m' lst (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: lrest)
    /\ bytes_at bsegs m' SP sbs
    /\ ACONST m' /\ aobj m' A SZ_TOKIT /\ accessible m' SP (Z.of_nat (length sbs)) /\ accessible m' lst 16.

Definition optit_pure (sp : word) (A lst SP lo : Z) (sbs : list byte) (lrest : list cell) : Prop :=
  SP + Z.of_nat (length sbs) < 2^64
  /\ (A + SZ_TOKIT <= SP \/ SP + Z.of_nat (length sbs) <= A)
  /\ (A + SZ_TOKIT <= lst \/ lst + Z.of_nat (cells_size (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: lrest)) <= A)
  /\ lo + TOKIT_STACK <= bv_unsigned sp /\ aceil <= lo
  /\ (bv_unsigned sp <= A \/ A + SZ_TOKIT <= lo)
  /\ (bv_unsigned sp <= SP \/ SP + Z.of_nat (length sbs) <= lo)
  /\ (bv_unsigned sp <= lst \/ lst + Z.of_nat (cells_size (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: lrest)) <= lo)
  /\ A mod 8 = 0 /\ lst mod 8 = 0
  /\ ((0 < length sbs)%nat -> 0 < SP).                                 (* [comment removed for export] *)

(* [comment removed for export] *)
Definition ok_saved (s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra : word) : list cell :=
  [C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

(* [comment removed for export] *)
Definition binc_ctx (m m1 : mem) (sp : word) (SV : list cell) (A lst SP lo : Z) (sbs : list byte)
    (lrest : list cell) (cur err : Z) (pad7 j8 : list byte) : Prop :=
  rw_cells bsegs m1 (bv_unsigned sp + -96) (CB 8 j8 :: SV)
  /\ rw_cells bsegs m1 A [C8 (wz lst); C8 (wz cur)]
  /\ rw_cells bsegs m1 (A + 16) [CB 16 zeros16]
  /\ rw_cells bsegs m1 (A + 32) [C1 (b8 err); CB 7 pad7]
  /\ rw_cells bsegs m1 lst (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: lrest)
  /\ bytes_at bsegs m1 SP sbs
  /\ stk bsegs m1 lo (bv_unsigned sp + -96)
  /\ munch [(lo, bv_unsigned sp); (A, A + SZ_TOKIT)]%Z m m1 /\ wmono bsegs m m1 /\ mem_inv bsegs m1
  /\ ok_side m A SP (Z.of_nat (length sbs)) lst.

(* [comment removed for export] *)
Lemma optit_join : forall m A x y (c0 c1 : cell) e p,
  rw_cells bsegs m A [C8 x; C8 y] -> rw_cells bsegs m (A + 16) [c0; c1] -> csize c0 = 8%nat -> csize c1 = 8%nat ->
  rw_cells bsegs m (A + 32) [C1 e; CB 7 p] ->
  rw_cells bsegs m A [C8 x; C8 y; c0; c1; C1 e; CB 7 p].
Proof.
  intros m A x y c0 c1 e p H V S0 S1 T.
  apply (proj2 (rw_cells_app bsegs m A [C8 x; C8 y] [c0; c1; C1 e; CB 7 p])). split; [exact H|].
  cbn [cells_size csize Nat.add]. change (Z.of_nat 16) with 16.
  apply (proj2 (rw_cells_app bsegs m (A + 16) [c0; c1] [C1 e; CB 7 p])). split; [exact V|].
  cbn [cells_size]. rewrite S0, S1. replace (A + 16 + Z.of_nat (8 + (8 + 0))) with (A + 32) by (cbn; lia). exact T.
Qed.
Lemma optit_join0 : forall m A x y e p,
  rw_cells bsegs m A [C8 x; C8 y] -> rw_cells bsegs m (A + 16) [CB 16 zeros16] ->
  rw_cells bsegs m (A + 32) [C1 e; CB 7 p] ->
  rw_cells bsegs m A [C8 x; C8 y; C8 (wz 0); C8 (wz 0); C1 e; CB 7 p].
Proof.
  intros m A x y e p H V T.
  assert (V' : rw_cells bsegs m (A + 16) [C8 (wz 0); C8 (wz 0)])
    by (eapply rw_cells_reshape; [exact V| cbn; repeat split; reflexivity| vm_compute; reflexivity]).
  apply optit_join; [exact H| exact V'| reflexivity| reflexivity| exact T].
Qed.

