Lemma binc_end : forall (cur : Z) rax ra sp gp tp t0 t1 t2 a0x a1x a2x a3x a4x a5x a6x a7x s6x s7x s8x s9x s10 s11
    s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (A lst SP lo : Z) (sbs : list byte) (lrest : list cell) (err : Z) (pad7 j8 : list byte),
  binc_ctx m m1 sp (ok_saved s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) A lst SP lo sbs lrest cur err pad7 j8 -> optit_pure sp A lst SP lo sbs lrest ->
