(* [comment removed for export] *)
Local Ltac call_sows HD SD MU WM CEIL ST MI WIN SEPW SEPA SEPS AL WNZ A cur E SP sbs lo sp :=
  let CELL := fresh "CELL" in let H1 := fresh "H1" in let SS := fresh "SS" in
  let ACc := fresh "ACc" in let AOc := fresh "AOc" in let AWc := fresh "AWc" in
  lazymatch type of HD with rw_cells _ _ _ [?c1; ?c2] => split_frameA HD [c1] [c2] H1 CELL end;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) => destruct (ok_side_now _ mc _ _ _ _ _ _ SD MU WM CEIL) as (ACc & AOc & AWc & _) end;
  pose proof skip_ows_spec as SS; unfold skip_ows_stmt, skip_ows_post, P_B_SKIP_OWS, SKIP_OWS_STACK in SS; unfold wz in SS;
  callZc (SS (A + 8) cur E SP sbs lo) (clear SS CELL ST);
  [ exact CELL | exact WIN | lia | lia | lia | clear - SEPW; unhideL; lia
  | rewrite ?unsigned_lit by lia; exact ST | rewrite ?unsigned_lit by lia; lia | exact CEIL
  | rewrite ?unsigned_lit by lia; clear - SEPA; unhideL; lia | rewrite ?unsigned_lit by lia; clear - SEPS; unhideL; lia
  | exact MI
  | clear - AL; unhideL; Z.div_mod_to_equations; lia
  | eapply aobj_sub_acc; [exact AOc| lia| lia| unfold SZ_TOKIT; lia]
  | eapply awin_sub; [exact (aobj_awin _ _ _ AOc)| lia| unfold SZ_TOKIT; lia]
  | intros _; exact AWc | exact ACc | exact WNZ | ];
  clear ACc AOc AWc;
  try match goal with H : bytes_at _ _ SP _, H' : bytes_at _ _ SP _ |- _ => clear H' end;
  lazymatch goal with H : bytes_at _ _ SP _ |- _ => try rename H into WIN end;
  lazymatch goal with C' : rw_cells _ _ (A + 8) [C8 _] |- _ => join_frameA H1 C' A; rename H1 into HD end.

(* [comment removed for export] *)
Lemma binc_loop : forall (mu i : nat) (nc : bool) rax ra sp gp tp t0 t1 t2 a1x a3x a4x a5x a6x a7x s10 s11
    s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (A lst SP lo : Z) (sbs : list byte) (lrest : list cell) (err : Z) (pad7 j8 : list byte),
  (length sbs - i < mu)%nat -> (i < length sbs)%nat ->
  (forall b, nth_error sbs i = Some b -> is_ws (zb b) = false) ->
  binc_ctx m m1 sp (ok_saved s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) A lst SP lo sbs lrest (SP + Z.of_nat i) err pad7 j8 -> optit_pure sp A lst SP lo sbs lrest ->
  evt bsegs (optit_post_c (optit_cells_after (tok_next nc (skipn i (zbytes sbs))) lst (SP + Z.of_nat i) err pad7)
               ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10 s11 F fc A lst SP lo sbs lrest m)
    (MS (binc_regs rax (Z_to_bv 64 (bv_unsigned sp + -96)) gp tp t0 t1 t2 (wz (SP + Z.of_nat i)) a1x (wz (if nc then 1 else 0)) a3x
              a4x a5x a6x a7x (SP + Z.of_nat (length sbs)) (wz 167040) (wz 44) (wz BNOT_TAB_TCHAR) (wz 2) s10 s11 t3 t4 t5 t6 A)
